orgs","received_events_url":"https://api.github.com/users/guimou/received_events","repos_url":"https://api.github.com/users/guimou/repos","site_admin":false,"starred_url":"https://api.github.com/users/guimou/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/guimou/subscriptions","type":"User","url":"https://api.github.com/users/guimou","user_view_type":"public"},"html_url":"https://github.com/rh-ai-community-plugins/apache-superset/commit/c27807f8ca390b01f56a166f32c82d5afdc756ef","node_id":"C_kwDOTbpVO9oAKGMyNzgwN2Y4Y2EzOTBiMDFmNTZhMTY2ZjMyYzgyZDVhZmRjNzU2ZWY","parents":[{"html_url":"https://github.com/rh-ai-community-plugins/apache-superset/commit/d248881fbf18eddf5a4442fed8015f7021a10b0e","sha":"d248881fbf18eddf5a4442fed8015f7021a10b0e","url":"https://api.github.com/repos/rh-ai-community-plugins/apache-superset/commits/d248881fbf18eddf5a4442fed8015f7021a10b0e"}],"sha":"c27807f8ca390b01f56a166f32c82d5afdc756ef","url":"https://api.github.com/repos/rh-ai-community-plugins/apache-superset/commits/c27807f8ca390b01f56a166f32c82d5afdc756ef"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/3944034?v=4","events_url":"https://api.github.com/users/guimou/events{/privacy}","followers_url":"https://api.github.com/users/guimou/followers","following_url":"https://api.github.com/users/guimou/following{/other_user}","gists_url":"https://api.github.com/users/guimou/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/guimou","id":3944034,"login":"guimou","node_id":"MDQ6VXNlcjM5NDQwMzQ=","organizations_url":"https://api.github.com/users/guimou/orgs","received_events_url":"https://api.github.com/users/guimou/received_events","repos_url":"https://api.github.com/users/guimou/repos","site_admin":false,"starred_url":"https://api.github.com/users/guimou/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/guimou/subscriptions","type":"User","url":"https://api.github.com/users/guimou","user_view_type":"public"},"comme